const initialiseYouTube=(root)=>{if(root.dataset.ready==='true')return;root.dataset.ready='true';root.querySelector('[data-youtube-activate]')?.addEventListener('click',()=>{const notice=root.querySelector('[data-youtube-notice]');if(window.CapellPrivacy?.allows?.('youtube')===false){notice.textContent='Video playback is disabled by your privacy choices.';return}const template=root.querySelector('[data-youtube-frame]');const frame=template?.content.firstElementChild?.cloneNode(true);if(!(frame instanceof HTMLIFrameElement))return;frame.src=`https://www.youtube-nocookie.com/embed/${encodeURIComponent(root.dataset.videoId)}?autoplay=1&rel=0&playsinline=1`;root.querySelector('.capell-youtube__frame')?.replaceChildren(frame)})};document.querySelectorAll('[data-capell-youtube]').forEach(initialiseYouTube);document.addEventListener('capell:content-ready',(event)=>event.target?.querySelectorAll?.('[data-capell-youtube]').forEach(initialiseYouTube));
